#!/usr/bin/env -S uv run --script
# /// script
# requires-python = ">=3.11"
# dependencies = []
# ///
"""Byte-equality and topology gate for the top-level `skills/` build artifact.

`skills/` is rebuilt wholesale by `scripts/build_skills.py` from two canonical
sources:

  * `assets/skills/init`                  -- the hand-authored init skill
  * `assets/bash/.claude/skills/speckit-*` -- generated by the asset-update
    workflow (`specify init --script sh`)

This gate fails CI when:

  * `skills/init` is not byte-identical to `assets/skills/init`
  * any `skills/speckit-*` copy drifts from `assets/bash/.claude/skills/`
  * the top-level `skills/` set is not exactly `{init}` plus the generated
    `speckit-*` set (any dangling extra entry is named)
  * either source set is empty (the gate must never pass vacuously)

Usage:
    uv run scripts/assert_bundled_skills.py
    uv run scripts/assert_bundled_skills.py --repo /path/to/checkout

Exits 2 on drift/dangling/missing copies, 1 when the comparison set is empty.
"""

from __future__ import annotations

import argparse
import os
import sys
from pathlib import Path

INIT_SOURCE_REL = Path("assets") / "skills" / "init"
SOURCE_REL = Path("assets") / "bash" / ".claude" / "skills"
BUNDLE_REL = Path("skills")
PREFIX = "speckit-"
INIT_NAME = "init"
REBUILD_HINT = (
    "skills/ is generated by scripts/build_skills.py from assets/skills/init "
    "and assets/bash/.claude/skills/; edit those sources and run "
    "'uv run scripts/build_skills.py' to rebuild."
)


def skill_dirs(parent: Path) -> dict[str, Path]:
    found: dict[str, Path] = {}
    if not parent.is_dir():
        return found
    for child in parent.iterdir():
        if child.is_dir() and child.name.startswith(PREFIX):
            found[child.name] = child
    return found


def rel_files(root: Path) -> dict[str, Path]:
    files: dict[str, Path] = {}
    if not root.is_dir():
        return files
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames.sort()
        filenames.sort()
        for name in filenames:
            path = Path(dirpath) / name
            files[path.relative_to(root).as_posix()] = path
    return files


def compare_trees(
    src: Path, dst: Path, label: str, source_rel: Path, bundle_rel: Path
) -> list[str]:
    """Return error messages if `dst` is not a byte-identical copy of `src`."""
    errors: list[str] = []
    src_shown = source_rel.as_posix()
    dst_shown = bundle_rel.as_posix()
    if not src.is_dir():
        errors.append(f"{label}: missing source {src_shown}")
        return errors
    if not dst.is_dir():
        errors.append(
            f"{label}: missing copy {dst_shown} "
            f"(generated from {src_shown}; the copy is generated -- edit the source)"
        )
        return errors

    src_files = rel_files(src)
    dst_files = rel_files(dst)
    only_src = sorted(set(src_files) - set(dst_files))
    only_dst = sorted(set(dst_files) - set(src_files))
    for rel in only_src:
        errors.append(
            f"{label}: missing file {dst_shown}/{rel} "
            f"(generated copy of {src_shown}/{rel})"
        )
    for rel in only_dst:
        errors.append(
            f"{label}: extra file {dst_shown}/{rel} "
            f"(not in canonical source {src_shown}; the copy is generated)"
        )
    for rel in sorted(set(src_files) & set(dst_files)):
        if src_files[rel].read_bytes() != dst_files[rel].read_bytes():
            errors.append(
                f"{label}: byte mismatch {dst_shown}/{rel} "
                f"(generated copy of {src_shown}/{rel}; edit the source, not the copy)"
            )
    return errors


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument(
        "--repo",
        type=Path,
        default=Path(__file__).resolve().parent.parent,
        help="repository checkout to inspect (default: this script's repository)",
    )
    args = parser.parse_args(argv)
    repo = args.repo.resolve()

    init_source = repo / INIT_SOURCE_REL
    init_bundle = repo / BUNDLE_REL / INIT_NAME
    source = skill_dirs(repo / SOURCE_REL)
    bundle_parent = repo / BUNDLE_REL
    bundle = skill_dirs(bundle_parent)

    errors: list[str] = []

    if not source:
        errors.append(f"no {PREFIX}* directories under {SOURCE_REL.as_posix()}")
    if not bundle:
        errors.append(f"no {PREFIX}* directories under {BUNDLE_REL.as_posix()}")

    only_source = sorted(set(source) - set(bundle))
    only_bundle = sorted(set(bundle) - set(source))
    for name in only_source:
        errors.append(
            f"missing copy: {BUNDLE_REL.as_posix()}/{name} "
            f"(generated from {(SOURCE_REL / name).as_posix()})"
        )
    for name in only_bundle:
        errors.append(
            f"extra copy: {BUNDLE_REL.as_posix()}/{name} "
            f"(not in {SOURCE_REL.as_posix()}; skills/ is a generated build artifact; "
            f"edit the canonical source under assets/ instead)"
        )

    verified = 0
    for name in sorted(set(source) & set(bundle)):
        tree_errors = compare_trees(
            source[name], bundle[name], name, SOURCE_REL / name, BUNDLE_REL / name
        )
        errors.extend(tree_errors)
        if not tree_errors:
            verified += 1

    errors.extend(
        compare_trees(init_source, init_bundle, INIT_NAME, INIT_SOURCE_REL, BUNDLE_REL / INIT_NAME)
    )

    expected = {INIT_NAME, *source}
    actual = set()
    if bundle_parent.is_dir():
        actual = {child.name for child in bundle_parent.iterdir()}
    dangling = sorted(actual - expected)
    missing_top = sorted(expected - actual)
    for name in dangling:
        errors.append(
            f"dangling top-level entry: {BUNDLE_REL.as_posix()}/{name} "
            f"(skills/ is a generated build artifact; remove this entry or edit "
            f"the canonical source under assets/ instead)"
        )
    for name in missing_top:
        source_hint = (
            INIT_SOURCE_REL.as_posix()
            if name == INIT_NAME
            else (SOURCE_REL / name).as_posix()
        )
        errors.append(
            f"missing top-level entry: {BUNDLE_REL.as_posix()}/{name} "
            f"(generated from {source_hint})"
        )

    if errors:
        print("error: bundled skills drifted from canonical sources:", file=sys.stderr)
        for message in errors:
            print(f"  - {message}", file=sys.stderr)
        print(REBUILD_HINT, file=sys.stderr)
        return 2

    if verified == 0:
        print(
            "error: no matching speckit-* skills to compare; "
            "the equality gate must never pass against an empty set",
            file=sys.stderr,
        )
        return 1

    print(
        f"ok: {verified} speckit-* skills byte-identical "
        f"({BUNDLE_REL.as_posix()}/speckit-* == {SOURCE_REL.as_posix()}/speckit-*); "
        f"{INIT_NAME} byte-identical "
        f"({BUNDLE_REL.as_posix()}/{INIT_NAME} == {INIT_SOURCE_REL.as_posix()}); "
        f"top-level {BUNDLE_REL.as_posix()}/ is exactly "
        f"{{{INIT_NAME}}} + {verified} {PREFIX}*"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
